import { DOC_SUB_TYPES, TEMPLATE_PATH } from "../../constants.mjs";
import EtheriaBaseMessage from "./base.mjs";

/**
 * Data model for Chat Messages generated by using an Item.
 * @extends {EtheriaBaseMessage}
 */
export default class EtheriaItemMessage extends EtheriaBaseMessage {
  /** @inheritDoc */
  static get metadata() {
    return foundry.utils.mergeObject(super.metadata, {
      type: DOC_SUB_TYPES.messages.item,
      actions: {
        rollAccuracy: EtheriaItemMessage.#onRollAccuracy,
        consumeItem: EtheriaItemMessage.#onConsumeItem,
        applyEffects: EtheriaItemMessage.#onApplyEffects,
      },
    });
  }

  /** @inheritdoc */
  static defineSchema() {
    const { fields } = foundry.data;
    return foundry.utils.mergeObject(super.defineSchema(), {
      item: new fields.SchemaField({
        uuid: new fields.DocumentUUIDField({ type: "Item" }),
        img: new fields.StringField({
          required: true,
          initial: "icons/svg/item-bag.svg",
        }),
        name: new fields.StringField({
          required: true,
          initial: "Unknown Item",
        }),
      }),
    });
  }

  /* -------------------------------------------------- */

  /**
   * Prepare the item data for the template.
   * @override
   */
  async _prepareContext(context) {
    await super._prepareContext(context);

    const item = await fromUuid(this.item.uuid);

    context.item = item;
    context.description = item
      ? await foundry.applications.ux.TextEditor.enrichHTML(
          item.system.description.value ?? "",
          {
            rollData: item?.getRollData(),
            relativeTo: item,
          },
        )
      : "";

    context.actions = Object.values(this.actions).map((a) => ({
      ...a,
      isIcon: !foundry.helpers.media.ImageHelper.hasImageExtension(a.icon),
    }));
  }

  /* -------------------------------------------------- */

  /** @override */
  async _renderHTML(element, context) {
    const template = `${TEMPLATE_PATH}/chat-messages/item.hbs`;
    const html = await foundry.applications.handlebars.renderTemplate(
      template,
      context,
    );
    element.insertAdjacentHTML("beforeend", html);
  }

  /* -------------------------------------------- */
  /*  Event Handlers                              */
  /* -------------------------------------------- */

  /**
   * @this {EtheriaItemMessage}
   * @type {foundry.applications.types.ApplicationClickAction}
   */
  static async #onRollAccuracy(_event, _target) {
    const item = await foundry.utils.fromUuid(this.item.uuid);
    if (!item) return;
    return await item._createAccuracyMessage?.();
  }

  /**
   * @this {EtheriaItemMessage}
   * @type {foundry.applications.types.ApplicationClickAction}
   */
  static async #onConsumeItem(_event, _target) {
    const item = await foundry.utils.fromUuid(this.item.uuid);
    if ( !item ) return;
    await item.consume();
  }

  /**
   * @this {EtheriaItemMessage}
   * @type {foundry.applications.types.ApplicationClickAction}
   */
  static async #onApplyEffects(_event, _target) {
    const item = await foundry.utils.fromUuid(this.item.uuid);
    if (!item) return;
    item.applyEffect();
  }
}
